head.script:
            
                function correctNumber( isString, value )
                {
                    if( isString )
                    {
                        return value;
                    }
                    else
                    {
                        // avoid sending of empty string
                        if( "" == value )
                        {
                            return null;
                        }

                        // replace decimal comma with decimal dot
                        value = "" + value; 
                        var commaRE = /,/;
                        return value.replace( commaRE, ".");
                    }
                }

                function setValue( isString, address, value )
                {
                    try
                    {
                        value = correctNumber( isString, value ); // null is returned if correction fails
                        if( value != null )
                        {
                            location.replace( location.pathname + "?set(" + address + "," + value + ")" );
                        }
                    }
                    catch(error)
                    {
                        // intentionaly do nothing
                    }
                }
